(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-987":{scenario:{company:"Lam Hồng Air",supervisor:{name:"Hoàng Mai Anh",role:{vi:"Tiếp viên trưởng",en:"Cabin Manager (Purser)"}},ref_code:"PIL-0417",title:{vi:"Đúng mã dịch vụ. Đúng số khách. An toàn trước tiên.",en:"Right service code. Right headcount. Safety first."},brief:{vi:"Chuyến bay 417 chuẩn bị đóng cửa. Danh sách đặt chỗ có 172 khách người lớn, 10 trẻ em và 4 em bé bế trên tay; 3 khách người lớn không có mặt đã được hạ tải. Khách ghế 3A không tự di chuyển được, phải nâng từ xe lăn vào tận ghế. Bản nháp danh sách PIL-0417 ghi mã SSR WCHR và tổng khách trên tàu 179. Đối chiếu danh sách khách đã duyệt, sửa hai trường và lập báo cáo bàn giao cho tiếp viên trưởng.",en:"Flight 417 is about to close its doors. The booking list shows 172 adults, 10 children and 4 lap infants; 3 adult no-shows have been offloaded. The passenger in seat 3A cannot move unaided and must be lifted from the wheelchair into the seat. Draft passenger list PIL-0417 shows SSR code WCHR and 179 passengers on board. Compare it with the approved passenger list, correct both fields and write a handover report for the purser."},reference_title:{vi:"Danh sách hành khách & loadsheet đã duyệt · PIL-0417",en:"Approved passenger list & loadsheet · PIL-0417"},fields:[{id:"SSR_CODE",label:{vi:"Mã dịch vụ đặc biệt ghế 3A",en:"Special service code, seat 3A"},initial:"WCHR",expected:"WCHC",choices:["WCHR","WCHS","WCHC"],reference:"Danh sách khách đặc biệt (SSR)",hint:{vi:"WCHR dành cho khách tự lên xuống bậc và đi lại trong khoang được; khách phải nâng vào ghế cần mức hỗ trợ cao nhất.",en:"WCHR is for passengers who can climb steps and walk in the cabin; a passenger lifted into the seat needs the highest level of help."}},{id:"PAX_TOTAL",label:{vi:"Tổng số hành khách trên tàu",en:"Total passengers on board"},initial:"179",expected:"183",reference:"Bảng cân bằng tải (loadsheet)",ref_value:{vi:"Đặt chỗ: 172 người lớn, 10 trẻ em, 4 em bé bế tay; 3 người lớn không có mặt đã hạ tải",en:"Booked: 172 adults, 10 children, 4 lap infants; 3 adult no-shows offloaded"},hint:{vi:"Em bé bế trên tay không chiếm ghế nhưng vẫn là người trên tàu và phải có trong số đếm.",en:"Lap infants take no seat but are still on board and must be counted."}}],sop32:{vi:"Tổng hành khách trên tàu = người lớn đã lên tàu + trẻ em + em bé bế tay, sau khi trừ khách không có mặt đã hạ tải; số đếm thực tế phải khớp loadsheet trước khi đóng cửa.",en:"Total passengers on board = adults boarded + children + lap infants, after removing offloaded no-shows; the physical headcount must match the loadsheet before door closure."},context:{label:"PIL / FLT 417",metrics:[{label:{vi:"Ghế đã bán",en:"Seats sold"},value:"182"},{label:{vi:"Em bé bế tay (INF)",en:"Lap infants (INF)"},value:"4"},{label:{vi:"Khách không có mặt",en:"No-shows"},value:"3"}]},crisis:{vi:"Một khách hạng thẻ vàng bế con 10 tháng tuổi đòi ngồi ghế 14C ở hàng cửa thoát hiểm cho rộng chân, dọa khiếu nại. Nhân viên mặt đất nói: “Chuyến ngắn thôi, cho anh ấy ngồi đi cho êm, kẻo trễ giờ đóng cửa.”",en:"A gold-tier passenger holding a 10-month-old demands seat 14C in the exit row for legroom and threatens to complain. The gate agent says: “It's a short flight, just let him sit there so we don't delay the door.”"},options:{safe:{vi:"Lịch sự từ chối vì khách bế em bé không được ngồi hàng cửa thoát hiểm, giải thích lý do an toàn, đề xuất ghế rộng khác ngoài hàng thoát hiểm và báo tiếp viên trưởng.",en:"Politely decline because passengers with infants may not sit in exit rows, explain the safety reason, offer another roomy non-exit seat and inform the purser."},shortcut:{vi:"Cho khách ngồi 14C để tránh khiếu nại và giữ đúng giờ.",en:"Let the passenger sit in 14C to avoid a complaint and stay on time."},wait:{vi:"Để khách tự ngồi đâu cũng được, sau khi cất cánh mới xử lý.",en:"Let the passenger sit anywhere and deal with it after take-off."}},questions:{vi:["Vì sao khách ghế 3A phải mang mã WCHC? Mã này thay đổi việc chuẩn bị nhân lực, thiết bị và kế hoạch sơ tán ra sao?","Trình bày cách tính tổng khách trên tàu và vì sao không được đóng cửa khi số đếm chưa khớp loadsheet."],en:["Why must the passenger in 3A be coded WCHC? How does this change staffing, equipment and evacuation planning?","Explain how you calculated the total on board and why doors must not close until the headcount matches the loadsheet."]},hints:{vi:["Đọc mô tả khả năng di chuyển của khách ghế 3A và so với định nghĩa từng mã SSR trên danh sách đã duyệt.","Áp dụng SOP mục 3.2: trừ khách đã hạ tải và nhớ cộng cả em bé bế tay.","Đọc lại SOP mục 4.2: quy định ghế hàng cửa thoát hiểm không có ngoại lệ cho hạng thẻ thành viên."],en:["Read how the passenger in 3A can move and compare it with each SSR definition on the approved list.","Apply SOP 3.2: remove offloaded passengers and remember to add lap infants.","Re-read SOP 4.2: exit row rules have no exceptions for loyalty tiers."]}},learning:{summary:{vi:"Tiếp viên hàng không bảo đảm an toàn, an ninh và phục vụ hành khách trên tàu bay: kiểm tra thiết bị khẩn nguy trước chuyến, hướng dẫn an toàn, giám sát khoang khách, hỗ trợ khách cần trợ giúp đặc biệt, xử lý tình huống y tế, gây rối, cháy khói và chỉ huy sơ tán khi khẩn cấp. Bên cạnh dịch vụ tận tâm, nghề đòi hỏi kỷ luật quy trình, giao tiếp đa văn hóa và bình tĩnh ra quyết định dưới áp lực.",en:"Cabin crew ensure safety, security and service on board: checking emergency equipment before flight, giving safety briefings, monitoring the cabin, assisting passengers with special needs, handling medical events, disruptive passengers, smoke or fire and leading evacuations. Alongside caring service, the role demands procedural discipline, cross-cultural communication and calm decisions under pressure."},responsibilities:{vi:["Họp trước chuyến, kiểm tra thiết bị khẩn nguy, cửa và khoang bếp theo danh mục.","Đón khách, kiểm tra ghế hàng cửa thoát hiểm, hành lý xách tay và khách cần hỗ trợ đặc biệt.","Trình diễn hướng dẫn an toàn, kiểm tra khoang khách trước cất cánh và hạ cánh.","Phục vụ ăn uống, bán hàng trên tàu và chăm sóc khách theo tiêu chuẩn của hãng.","Sơ cứu, xử lý khách gây rối, cháy khói trong khoang và tổ chức sơ tán khi khẩn cấp."],en:["Attend the pre-flight briefing and check emergency equipment, doors and galleys against checklists.","Board passengers and check exit rows, cabin baggage and passengers needing special assistance.","Deliver the safety demonstration and secure the cabin before take-off and landing.","Serve meals, run on-board sales and care for passengers to the airline standard.","Give first aid, manage disruptive passengers, smoke or fire in the cabin and lead evacuations."]},competencies:[{name:{vi:"An toàn & thoát hiểm",en:"Safety & evacuation"},desc:{vi:"Thuộc vị trí, cách dùng thiết bị khẩn nguy và lệnh sơ tán trên từng loại tàu bay.",en:"Know the location and use of emergency equipment and the evacuation commands for each aircraft type."}},{name:{vi:"Phục vụ khách hàng",en:"Customer service"},desc:{vi:"Chăm sóc tận tình, nhận diện nhu cầu đặc biệt và giữ trải nghiệm nhất quán.",en:"Provide attentive care, recognise special needs and keep the experience consistent."}},{name:{vi:"Xử lý xung đột",en:"Conflict handling"},desc:{vi:"Từ chối yêu cầu không an toàn một cách lịch sự, đưa ra lựa chọn thay thế và hạ nhiệt tình huống.",en:"Decline unsafe requests politely, offer alternatives and de-escalate."}},{name:{vi:"Sơ cứu & y tế hàng không",en:"First aid & aviation medicine"},desc:{vi:"Đánh giá ban đầu, sơ cứu, dùng thiết bị y tế trên tàu và phối hợp hỗ trợ y tế từ mặt đất.",en:"Assess, give first aid, use on-board medical kits and coordinate ground medical support."}},{name:{vi:"Phối hợp tổ bay (CRM)",en:"Crew resource management"},desc:{vi:"Trao đổi rõ ràng với tổ lái và tiếp viên khác, báo cáo kịp thời mọi bất thường.",en:"Communicate clearly with the flight deck and other crew and report any irregularity promptly."}}],knowledge:{vi:["Phụ lục 6 Công ước Chicago (ICAO Annex 6) về khai thác tàu bay và yêu cầu đối với tổ tiếp viên.","Quy định ghế hàng cửa thoát hiểm: khách phải đủ khả năng hỗ trợ mở cửa, không bế em bé, không cần trợ giúp đặc biệt.","Mã yêu cầu dịch vụ đặc biệt của IATA như WCHR, WCHS, WCHC, UMNR, MEDA và thủ tục phục vụ tương ứng.","Hướng dẫn ICAO Doc 9481 về ứng phó sự cố hàng nguy hiểm trên tàu bay, như pin lithium quá nhiệt.","Nguyên tắc quản lý nguồn lực tổ bay (CRM) và quy trình xử lý hành khách gây rối."],en:["ICAO Annex 6 on aircraft operations and cabin crew requirements.","Exit row rules: passengers must be able to assist with the exit, not hold an infant and not need special help.","IATA special service request codes such as WCHR, WCHS, WCHC, UMNR and MEDA and the matching procedures.","ICAO Doc 9481 on responding to dangerous goods incidents on board, such as overheating lithium batteries.","Crew resource management (CRM) principles and procedures for disruptive passengers."]},tools:["Danh mục kiểm tra thiết bị khẩn nguy","Hệ thống thông báo & liên lạc nội bộ","Bộ sơ cứu & túi y tế","Bình chữa cháy & túi cách ly pin lithium","Thiết bị bán hàng trên tàu"],kpis:{vi:["Tỷ lệ chuyến đóng cửa đúng giờ mà không vi phạm quy trình an toàn.","Điểm hài lòng hành khách theo khảo sát sau chuyến.","Số sai lệch an toàn bị phát hiện qua kiểm tra đột xuất (mục tiêu bằng 0).","Tỷ lệ báo cáo sự kiện khoang khách đầy đủ, đúng hạn."],en:["Share of flights closing on time with no safety procedure breach.","Passenger satisfaction score from post-flight surveys.","Safety deviations found in spot checks (target zero).","Share of cabin event reports filed completely and on time."]},day:[{time:"05:30",vi:"Điểm danh, họp tổ bay, nhận thông tin chuyến bay và danh sách khách đặc biệt.",en:"Sign in, attend the crew briefing and receive flight details and the special passenger list."},{time:"06:15",vi:"Kiểm tra thiết bị khẩn nguy, khoang bếp và vệ sinh khoang khách.",en:"Check emergency equipment, galleys and cabin cleanliness."},{time:"06:45",vi:"Đón khách, kiểm tra hàng ghế thoát hiểm và đếm khách đối chiếu loadsheet.",en:"Board passengers, check exit rows and do a headcount against the loadsheet."},{time:"07:30",vi:"Phục vụ trên chuyến bay, theo dõi khách cần hỗ trợ và tình trạng khoang.",en:"Serve in flight and monitor passengers needing help and the cabin condition."},{time:"09:30",vi:"Hạ cánh, hỗ trợ khách xe lăn rời tàu, viết báo cáo chuyến và bàn giao.",en:"Land, help wheelchair passengers disembark, write the flight report and hand over."}],mistakes:{vi:["Quên cộng em bé bế tay khi đếm khách khiến số đếm không khớp loadsheet.","Xếp khách bế em bé hoặc khách cần hỗ trợ vào hàng ghế cửa thoát hiểm.","Chọn sai mã hỗ trợ xe lăn, khiến thiếu nhân lực và thiết bị nâng khi lên xuống tàu."],en:["Forgetting lap infants in the headcount so it does not match the loadsheet.","Seating a passenger with an infant or needing help in an exit row.","Choosing the wrong wheelchair code, leaving too few staff and no lifting equipment at boarding."]},career:[{vi:"Tiếp viên hạng phổ thông",en:"Economy cabin crew"},{vi:"Tiếp viên hạng thương gia",en:"Business class cabin crew"},{vi:"Tiếp viên trưởng",en:"Purser / Cabin manager"},{vi:"Giáo viên huấn luyện, quản lý đội tiếp viên",en:"Cabin crew instructor, crew manager"}],glossary:[{term:"SSR",vi:"Mã yêu cầu dịch vụ đặc biệt gắn với đặt chỗ, báo cho tổ bay biết nhu cầu của khách.",en:"Special service request code on the booking that tells the crew a passenger's needs."},{term:"WCHC",vi:"Khách không tự di chuyển được, cần xe lăn và hỗ trợ đến tận ghế ngồi.",en:"Passenger who is completely immobile and needs a wheelchair and help right to the seat."},{term:"Loadsheet",vi:"Bảng cân bằng tải ghi số khách, hàng hóa, nhiên liệu và trọng tâm tàu bay.",en:"Load and trim sheet listing passengers, cargo, fuel and the aircraft centre of gravity."},{term:"Exit row",vi:"Hàng ghế cạnh cửa thoát hiểm, khách ngồi đó phải có khả năng hỗ trợ mở cửa khi khẩn cấp.",en:"Seats next to an emergency exit whose occupants must be able to help open it."},{term:"CRM",vi:"Quản lý nguồn lực tổ bay: phối hợp, giao tiếp, ra quyết định chung giữa các thành viên.",en:"Crew resource management: teamwork, communication and shared decision making."}],quiz:[{q:{vi:"Khách đi lại được trong khoang nhưng không tự lên xuống cầu thang dùng mã nào?",en:"Which code fits a passenger who can walk in the cabin but cannot climb steps?"},options:{vi:["WCHR","WCHC","WCHS","MEDA"],en:["WCHR","WCHC","WCHS","MEDA"]},answer:2,explain:{vi:"WCHS: không lên xuống bậc được nhưng tự đi lại trong khoang; WCHC: không tự di chuyển.",en:"WCHS: cannot manage steps but can walk in the cabin; WCHC: completely immobile."}},{q:{vi:"Chuyến có 150 người lớn đã lên tàu, 6 trẻ em và 3 em bé bế tay. Tổng hành khách trên tàu là bao nhiêu?",en:"A flight has 150 adults boarded, 6 children and 3 lap infants. How many passengers are on board?"},options:{vi:["156","159","153","150"],en:["156","159","153","150"]},answer:1,explain:{vi:"150 + 6 + 3 = 159; em bé bế tay vẫn phải tính vào số người trên tàu.",en:"150 + 6 + 3 = 159; lap infants are still counted on board."}},{q:{vi:"Khách hạng thẻ cao bế em bé đòi ngồi hàng cửa thoát hiểm. Bạn làm gì?",en:"A top-tier passenger with an infant insists on an exit row seat. What do you do?"},options:{vi:["Lịch sự từ chối, giải thích lý do an toàn và đề xuất ghế khác","Cho ngồi vì là khách quan trọng","Cho ngồi nếu khách ký cam kết","Mặc kệ, để tiếp viên khác xử lý"],en:["Politely decline, explain the safety reason and offer another seat","Allow it because the passenger is important","Allow it if the passenger signs a waiver","Ignore it and leave it to another crew member"]},answer:0,explain:{vi:"Quy định ghế hàng thoát hiểm là yêu cầu an toàn bắt buộc, không có ngoại lệ thương mại.",en:"Exit row rules are mandatory safety requirements with no commercial exceptions."}},{q:{vi:"Sạc dự phòng của khách bốc khói trong khoang. Hành động ưu tiên là gì?",en:"A passenger's power bank starts smoking in the cabin. What is the priority action?"},options:{vi:["Chờ hạ cánh rồi xử lý","Mở cửa sổ cho thoát khói","Bỏ vào thùng rác khoang bếp","Báo tổ lái, dập lửa nếu có, làm mát bằng nước hoặc chất lỏng không cồn và cách ly thiết bị"],en:["Wait until landing","Open a window to vent the smoke","Put it in the galley waste bin","Alert the flight deck, extinguish any fire, cool it with water or a non-alcoholic liquid and isolate it"]},answer:3,explain:{vi:"Theo hướng dẫn ứng phó pin lithium, cần thông báo tổ lái, dập lửa, làm mát để ngăn cháy lan nhiệt và theo dõi liên tục.",en:"Lithium battery guidance calls for alerting the flight deck, extinguishing, cooling to stop thermal runaway and monitoring."}}],tools_en:["Emergency equipment checklist","PA & interphone system","First aid kit & medical kit","Extinguisher & lithium battery containment bag","Inflight sales equipment"]}}})})(window.KKR);
